export function getPhase3Service(slug: string): Phase3Service | undefined {
  return PHASE3_SERVICES.find((row) => row.slug === slug)
}

export function phase3Image(category: string): string {
  return IMG[category] ?? '/images/services/siddhi-ai.jpg'
}

